const MASCOT_OPTIONS = Object.entries(MASCOT_PROFILES).map(([value, profile]) => ({
  title: profile.label,
  value,
}));

function resolveMascotProfile(name) {
  return MASCOT_PROFILES[name] || MASCOT_PROFILES.chibiterasu
}

function resolveMascotImage(name, imageName) {
  const profile = resolveMascotProfile(name);
  return profile.images[imageName] || SHIMEJI_IMAGES[imageName] || SHIMEJI_IMAGES.shime1
}

const GROUND_FOOT_ANCHOR = [64, 128];
const RUN_BODY_ANCHOR = [64, 138];
const DASH_BODY_ANCHOR = [64, 135];
const PULL_OUT_BODY_ANCHOR = [96, 128];

const WALL_GRAB_ANCHOR = [41, 128];

const CEILING_GRAB_ANCHOR = [64, 48];
