const CEILING_CRAWL_LOW_ANCHOR = [64, 55];
const CEILING_CRAWL_STRETCH_ANCHOR = [64, 58];
const CEILING_CRAWL_RECOVER_ANCHOR = [64, 52];

function pose(name, anchor = GROUND_FOOT_ANCHOR, velocity = [0, 0], duration = 250) {
  return {
    imageName: name,
    anchor: [...anchor],
    velocity: [...velocity],
    duration,
  }
}

